<script setup>
import { ref,computed,onMounted,onBeforeUnmount } from 'vue'
import { api } from '../api'
import { storageKey,localDate,accountEpoch,displayTime } from '../session'
import { useWorkflowWrite } from '../composables/useWorkflowWrite'
import ConfirmDialog from './ui/ConfirmDialog.vue'
import { queuePriceSweep } from '../pricingSweep'
const emit=defineEmits(['changed']),items=ref([]),quotes=ref([]),checks=ref([]),balance=ref(0),error=ref(''),notice=ref(''),choice=ref(null),writes=useWorkflowWrite('reward-shop'),form=ref({name:'',reward_kind:'item',minutes:30,price_yuan:null,description:''}),epoch=accountEpoch
const key=storageKey('reward-draft');let alive=true,timer=null,checking=false
const adding=ref(false),removing=ref(null)
const activeItems=computed(()=>items.value.filter(item=>item.enabled)),archivedItems=computed(()=>items.value.filter(item=>!item.enabled))
try{form.value={...form.value,...JSON.parse(localStorage.getItem(key)||'{}')}}catch{}
const pendingFailed=computed(()=>quotes.value.some(q=>q.request_key===writes.pending.value?.body.request_key&&q.state==='failed'))
function cache(){try{localStorage.setItem(key,JSON.stringify(form.value))}catch{}}
async function load(){try{const [shop,q,c]=await Promise.all([api.listShopItems(),api.flow('/reward-quotes'),api.flow('/pricing-checks')]);if(!alive||epoch!==accountEpoch)return;items.value=shop.items;balance.value=shop.balance;quotes.value=q.items;checks.value=c.items;clearTimeout(timer);if(c.items.some(r=>['queued','running'].includes(r.state)))timer=setTimeout(load,2200)}catch(e){if(alive&&epoch===accountEpoch)error.value=e.message}}
async function check(){if(writes.pending.value||checking)return;checking=true;try{const result=await queuePriceSweep({storage:localStorage,key:storageKey('price-check:'+localDate()),request:body=>api.flow('/pricing-checks',body),current:()=>alive&&epoch===accountEpoch});if(alive&&epoch===accountEpoch){if(result.reason==='daily_limit')notice.value='今天已安排10项价格检查，其余授权奖励会在之后优先安排。';await load()}}catch(e){if(alive&&epoch===accountEpoch)error.value='价格检查结果待确认；下次进入会恢复原请求。'+e.message}finally{checking=false}}
async function act(path,body,method='POST'){try{const result=await writes.send(path,body,method);if(!alive||epoch!==accountEpoch)return;await load();error.value='';emit('changed');return result}catch(e){if(alive&&epoch===accountEpoch){error.value=e.message;await load()}return null}}
async function price(){cache();const name=form.value.name;const result=await act('/reward-quotes',{...form.value,price_yuan:form.value.price_yuan===''?null:form.value.price_yuan,auto_check:true});if(result?.item){adding.value=false;notice.value='奖励已按本人模型的有效价格加入。';if(form.value.name===name){form.value.name='';form.value.description='';cache()}}}
async function recover(){const p=writes.pending.value;if(p)await act(p.path,p.body,p.method)}
async function redeem(){const item=choice.value;if(!item)return;const result=await act('/shop/items/'+item.id+'/redeem',{expected_version:item.updated_at});if(result){choice.value=null;notice.value='兑换成功；这张券按购买价格与时长保留。'}else if(items.value.find(i=>i.id===item.id)?.updated_at!==item.updated_at)choice.value=null}
async function permission(item){const result=await act('/shop/items/'+item.id+'/automatic-pricing',{expected_version:item.updated_at,enabled:!item.auto_pricing,acknowledge:!item.auto_pricing});if(result)await check()}
async function disable(item){await act('/shop/items/'+item.id,{enabled:!item.enabled},'PUT')}
async function remove(){const item=removing.value;if(!item)return;const result=await act('/shop/items/'+item.id,{expected_version:item.updated_at},'DELETE');if(result){removing.value=null;notice.value='已从奖励列表移除；旧券和兑换账目保留。'}}
defineExpose({reload:load})
onMounted(async()=>{await load();await check()});onBeforeUnmount(()=>{alive=false;clearTimeout(timer)})

const props=defineProps({management:Boolean})
</script>
<template><div v-if="writes.pending.value" class="action-group"><button class="btn" :disabled="writes.busy.value" @click="recover">恢复上次请求结果</button><button v-if="writes.pending.value.path==='/reward-quotes'&&pendingFailed" class="btn" :disabled="writes.busy.value" @click="writes.discardSuggestion();error=''">保留草稿，结束失败的定价请求</button></div><p v-if="error&&!adding" class="error" role="alert">{{ error }}</p><p v-if="notice&&!adding" role="status">{{ notice }}</p><details class="card reward-add" :open="adding" @toggle="adding=$event.target.open"><summary>添加自己的心愿</summary><p>写下想要的物品、体验或额外娱乐。AI参考你明确授权的个人背景、购买力与实际使用，不设统一汇率。</p><p v-if="error" class="error" role="alert">{{ error }} <RouterLink to="/settings">查看模型设置</RouterLink></p><p v-if="notice" role="status">{{ notice }}</p><form @submit.prevent="price" @input="cache"><label>想要的奖励<input v-model="form.name" maxlength="120" placeholder="例如：一本想读的书 / 一小时额外娱乐" required/></label><div class="form-grid"><label>形式<select v-model="form.reward_kind"><option value="item">物品</option><option value="experience">体验</option><option value="entertainment">计时娱乐</option></select></label><label v-if="form.reward_kind==='entertainment'">每次分钟<input type="number" min="1" max="1440" v-model.number="form.minutes"/></label><label>现实参考价（可空）<input type="number" min="0" step="0.01" v-model.number="form.price_yuan"/></label></div><label>说明与期望频率<textarea v-model="form.description" maxlength="2000" rows="2"/></label><p class="muted">点击即授权本次定价及之后进入奖励区时的有限价格检查。有效初价直接加入，后续每天最多更新一次、幅度不超过20%；购买仍需你确认。</p><button class="btn primary" :disabled="writes.busy.value||!!writes.pending.value">{{ writes.busy.value?'正在为心愿定价…':'AI 定价并加入心愿' }}</button></form></details><section class="card"><div class="section-heading"><h2>{{ management?'管理自己的奖励':'你的奖励' }}</h2><span class="tag">{{ balance }} 币</span></div><p v-if="!activeItems.length" class="muted">还没有奖励，从一个自己想要的心愿开始。必要休息不需要金币。</p><article v-for="item in activeItems" :key="item.id" class="reward-row"><div class="section-heading"><h3>{{ item.name }}</h3><strong class="reward-price">{{ item.coin_price }} <small>币</small></strong></div><details :open="management"><summary>{{ management?'管理与定价依据':'定价依据' }}</summary><p>{{ item.pricing_reason }}</p><p class="muted">{{ item.worth_note }}</p><p v-if="item.priced_at" class="muted">评估于 {{ displayTime(item.priced_at) }}</p><p v-else class="muted">原有价格与权益保留。</p><div v-if="management" class="action-group"><button class="text-button" :disabled="writes.busy.value" @click="disable(item)">{{ item.enabled?'停用心愿':'重新启用' }}</button><button class="text-button" :disabled="writes.busy.value" @click="permission(item)">{{ item.auto_pricing?'关闭自动价格检查':'允许本人模型按日检查价格' }}</button><button class="text-button danger" :disabled="writes.busy.value||!!writes.pending.value" @click="removing={...item}">移除奖励</button></div></details><button v-if="!management" class="btn primary" :disabled="writes.busy.value||!!writes.pending.value||balance<item.coin_price" @click="choice={...item}">确认兑换</button></article><details v-if="archivedItems.length" class="archived-rewards"><summary>已移除 / 停用的奖励 · {{ archivedItems.length }}</summary><article v-for="item in archivedItems" :key="item.id"><p>{{ item.name }} · {{ item.coin_price }} 币</p><button class="text-button" :disabled="writes.busy.value||!!writes.pending.value" @click="disable(item)">恢复到奖励列表</button></article></details><details v-if="checks.length"><summary>自动价格检查状态</summary><p v-for="r in checks.slice(0,10)" :key="r.id">{{ r.local_date }} · {{ items.find(i=>i.id===r.item_id)?.name||'原有奖励' }} · {{ {queued:'已排队，可暂离后查看',running:'正在定价',completed:'本次检查完成',failed:'本次检查失败，当前有效价保留'}[r.state] }}<span v-if="r.error_code"> · {{ r.error_code }}</span><button v-if="r.state==='failed'&&r.version<6&&r.local_date===localDate()" class="text-button" :disabled="writes.busy.value" @click="act('/pricing-checks/'+r.id+'/retry',{expected_version:r.version})">主动重试本次价格检查（最多一次）</button></p><p>失败不自动循环重试；不会按新价补收旧券差额。</p></details></section><ConfirmDialog :open="!!choice" title="确认兑换" confirm-label="确认兑换这份奖励" :busy="writes.busy.value" @cancel="choice=null" @confirm="redeem"><p>{{ choice?.name }} · 本次 {{ choice?.coin_price }} 币</p><p>兑换后余额 {{ balance-(choice?.coin_price||0) }} 币。购买锁定这张券的价格和原始时长。</p><p v-if="error" class="error" role="alert">{{ error }}</p></ConfirmDialog><ConfirmDialog :open="!!removing" title="移除奖励" confirm-label="确认移除奖励" :busy="writes.busy.value" @cancel="removing=null" @confirm="remove"><p>{{ removing?.name }}</p><p>从当前列表隐藏，停止自动价格检查；已购买的券和历史账目保留。之后可从已移除列表恢复。</p><p v-if="error" class="error" role="alert">{{ error }}</p></ConfirmDialog></template>
